# Surah Al-Baqarah (chapter 2) — part 23: ayat 221-230 (IDs 228-237)
SURAH = 2

ENTRIES = {
228: (
"اور مشرک عورتوں سے نکاح نہ کرو جب تک وہ ایمان نہ لائیں — اور ایمان والی باندی مشرکہ سے بہتر ہے چاہے وہ تمہیں اچھی لگے — اور مشرک مردوں کو نکاح نہ کراؤ جب تک وہ ایمان نہ لائیں — اور ایمان والا غلام مشرک سے بہتر ہے چاہے وہ تمہیں اچھا لگے — یہی لوگ آگ کی دعوت دیتے ہیں — اور اللہ (اپنی) رحمت اور مغفرت کے ساتھ جنت کی طرف بلاتا ہے — اور اپنی آیات لوگوں کے لیے بیان کرتا ہے — شاید کہ وہ نصیحت حاصل کریں۔",
"""۱۔ نکاح کے ایمانی اصول بیان ہو رہے ہیں — مسلمان عورت/مرد کا رشتہ صرف ایمان والوں سے۔
۲۔ ’’وَلَا تَنكِحُوا الْمُشْرِكَاتِ حَتَّىٰ يُؤْمِنَّ‘‘ — مشرک عورتوں سے نکاح نہ کرو جب تک وہ ایمان نہ لائیں — یعنی مسلمان مرد مشرک عورت سے نکاح نہ کرے۔
۳۔ ’’وَلَأَمَۃٌ مُّؤْمِنَۃٌ خَيْرٌ مِّن مُّشْرِكَۃٍ وَلَوْ أَعْجَبَتْكُمْ‘‘ — اور ایمان والی باندی مشرکہ سے بہتر ہے چاہے وہ تمہیں اچھی لگے — یعنی ایمان ہی اصل معیار ہے، مال و جمال نہیں۔
۴۔ ’’وَلَا تُنكِحُوا الْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا‘‘ — اور مشرک مردوں کو نکاح نہ کراؤ جب تک وہ ایمان نہ لائیں — یعنی مسلمان عورت مشرک مرد سے نکاح نہیں کر سکتی۔
۵۔ ’’وَلَعَبْدٌ مُّؤْمِنٌ خَيْرٌ مِّن مُّشْرِكٍ وَلَوْ أَعْجَبَكُمْ‘‘ — اور ایمان والا غلام مشرک سے بہتر ہے چاہے وہ تمہیں اچھا لگے۔
۶۔ ’’أُولَٰئِكَ يَدْعُونَ إِلَى النَّارِ وَاللّٰہُ يَدْعُو إِلَى الْجَنَّۃِ وَالْمَغْفِرَۃِ بِإِذْنِهِ‘‘ — یہی لوگ آگ کی دعوت دیتے ہیں — اور اللہ (اپنی) رحمت اور مغفرت کے ساتھ جنت کی طرف بلاتا ہے — یعنی مشرکین کا معاشرہ انسان کو دوزخ کی طرف لے جاتا ہے، اللہ کا نظام جنت کی طرف۔
۷۔ عملی سبق: رشتہ انتخاب میں ایمان کو سب سے پہلے معیار بنائیں؛ دنیاوی جمال اور مال ایمان کی جگہ نہیں لے سکتے۔"""
),
229: (
"اور وہ آپ سے حیض (ماہواری) کے بارے میں پوچھتے ہیں — کہہ دیجیے: یہ تکلیف ہے — پس حیض کی حالت میں عورتوں سے دور رہو — اور ان کے پاس نہ جاؤ جب تک وہ پاک نہ ہو جائیں — پھر جب وہ پاک ہو جائیں تو ان کے پاس جاؤ اس طرح جیسے اللہ نے تمہیں حکم دیا — بے شک اللہ توبہ کرنے والوں کو پسند کرتا ہے اور پاک رہنے والوں کو پسند کرتا ہے۔",
"""۱۔ حیض (ماہواری) کی حالت میں میاں بیوی تعلقات کا حکم۔
۲۔ ’’قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ‘‘ — کہہ دیجیے: یہ تکلیف ہے — پس حیض کی حالت میں عورتوں سے دور رہو — یعنی حیض کے دوران تعلق منع ہے۔
۳۔ ’’وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ‘‘ — اور ان کے پاس نہ جاؤ جب تک وہ پاک نہ ہو جائیں (خون بند ہو جائے اور غسل کریں)۔
۴۔ ’’فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللّٰہُ‘‘ — پھر جب وہ پاک ہو جائیں تو ان کے پاس جاؤ اس طرح جیسے اللہ نے تمہیں حکم دیا — یعنی پاکیزگی کے بعد تعلق جائز ہے۔
۵۔ ’’إِنَّ اللّٰہَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ‘‘ — بے شک اللہ توبہ کرنے والوں کو پسند کرتا ہے اور پاک رہنے والوں کو پسند کرتا ہے — یعنی توبہ اور طہارت اللہ کی پسند ہیں۔
۶۔ عملی سبق: میاں بیوی ہر حال میں شریعت کے حدود کی پابندی کریں؛ حیض کی حالت میں احترام اور صبر ضروری ہے۔"""
),
230: (
"تمہاری بیویاں تمہاری کھیتی ہیں — پس اپنی کھیتی میں جہاں چاہو آؤ — اور اپنے لیے (نیک عمل) آگے بھیج دو — اور اللہ سے ڈرو اور جان لو کہ تم اس سے ملو گے — اور ایمان والوں کو خوشخبری سناؤ۔",
"""۱۔ میاں بیوی کے تعلقات کی مکمل تصویر — محبت، حدود اور آخرت کی سوچ۔
۲۔ ’’نِسَاؤُكُمْ حَرْثٌ لَّكُمْ فَأْتُوا حَرْثَكُمْ أَنَّىٰ شِئْتُمْ‘‘ — تمہاری بیویاں تمہاری کھیتی ہیں — پس اپنی کھیتی میں جہاں چاہو آؤ — یعنی تعلقات صحیح طریقے اور اپنی سہولت کے مطابق ہو سکتے ہیں، بشرط کہ حدودِ شریعت کے اندر ہوں۔
۳۔ ’’وَقَدِّمُوا لِأَنفُسِكُمْ‘‘ — اور اپنے لیے (نیک عمل) آگے بھیج دو — یعنی تعلق سے پہلے اللہ کی مرضی اور نیک نیت۔
۴۔ ’’وَاتَّقُوا اللّٰہَ وَاعْلَمُوا أَنَّكُم مُّلَاقُوهُ‘‘ — اور اللہ سے ڈرو اور جان لو کہ تم اس سے ملو گے — یعنی میاں بیوی تعلق کے باوجود اللہ کی عدالت سے ڈرنا ہے۔
۵۔ ’’وَبَشِّرِ الْمُؤْمِنِينَ‘‘ — اور ایمان والوں کو خوشخبری سناؤ۔
۶۔ عملی سبق: میاں بیوی کے تعلقات میں محبت، حدود اور آخرت کی تلاوت — سب شامل ہیں۔"""
),
231: (
"اور اپنی قسموں کو اللہ کے لیے (عذر) بنا کر نیکی، تقویٰ اور لوگوں کے درمیان صلح سے باز نہ رہو — اور اللہ سننے والا جاننے والا ہے۔",
"""۱۔ قسم کو عذر بنا کر نیکی اور صلح سے باز نہ رہنے کا حکم۔
۲۔ ’’وَلَا تَجْعَلُوا اللّٰہَ عُرْضَۃً لِّأَيْمَانِكُمْ‘‘ — اور اپنی قسموں کو اللہ کے لیے (عذر) بنا کر — یعنی اگر کوئی قسم کھا لی تو اس کی وجہ سے نیکی ترک نہ کرو۔
۳۔ ’’أَن تَبَرُّوا وَتَتَّقُوا وَتُصْلِحُوا بَيْنَ النَّاسِ‘‘ — نیکی، تقویٰ اور لوگوں کے درمیان صلح سے باز نہ رہو — یعنی قسم کے بہانے سے صلح اور نیکی نہ چھوڑو۔
۴۔ ’’وَاللّٰہُ سَمِيعٌ عَلِيمٌ‘‘ — اور اللہ سننے والا جاننے والا ہے۔
۵۔ عملی سبق: اگر قسم نیکی اور صلح کی راہ میں رکاوٹ بنے تو قسم کا کفارہ دے کر وہ نیکی کرو۔"""
),
232: (
"اللہ تمہیں تمہاری فضول قسموں پر مؤاخذہ نہیں کرے گا — مگر وہی مؤاخذہ کرے گا جو تمہارے دل کماتے ہیں — اور اللہ بخشنے والا، تحمل والا ہے۔",
"""۱۔ لغو (بے بنیاد) قسموں پر کوئی گرفت نہیں — صرف جان بوجھ کر دل سے کی گئی قسموں پر مؤاخذہ۔
۲۔ ’’لَّا يُؤَاخِذُكُمُ اللّٰہُ بِاللَّغْوِ فِي أَيْمَانِكُمْ‘‘ — اللہ تمہیں تمہاری فضول قسموں پر مؤاخذہ نہیں کرے گا — یعنی لاپرواہی سے دی گئی قسموں کا حساب نہیں۔
۳۔ ’’وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ‘‘ — مگر وہی مؤاخذہ کرے گا جو تمہارے دل کماتے ہیں — یعنی سوچ سمجھ کر اور دل کی نیت سے دی گئی قسمیں۔
۴۔ ’’وَاللّٰہُ غَفُورٌ حَلِيمٌ‘‘ — اور اللہ بخشنے والا، تحمل والا ہے۔
۵۔ عملی سبق: قسم کھانے سے پہلے سوچو؛ لغو قسموں کا اللہ پر کوئی وبال نہیں مگر دل سے نیت کی قسموں کا حساب ہوگا۔"""
),
233: (
"جن لوگوں نے اپنی بیویوں سے (قلیل) تعلق قطع کرنے کی قسم کھائی — ان کے لیے چار مہینے کی مہلت ہے — پھر اگر وہ رجوع کریں تو بے شک اللہ بخشنے والا، رحم والا ہے۔",
"""۱۔ ایلاء (بیوی سے تعلق قطع کرنے کی قسم) کا حکم — چار مہینوں کی مہلت۔
۲۔ ’’لِّلَّذِينَ يُؤْلُونَ مِن نِّسَائِهِمْ تَرَبُّصُ أَرْبَعَۃِ أَشْهُرٍ‘‘ — جن لوگوں نے اپنی بیویوں سے (قلیل) تعلق قطع کرنے کی قسم کھائی — ان کے لیے چار مہینے کی مہلت ہے — یعنی ایلاء کرنے والا چار مہینوں تک انتظار کرے۔
۳۔ ’’فَإِن فَاءُوا فَإِنَّ اللّٰہَ غَفُورٌ رَّحِيمٌ‘‘ — پھر اگر وہ رجوع کریں تو بے شک اللہ بخشنے والا، رحم والا ہے — یعنی واپسی کی توبہ اور تعلق دوبارہ شروع کرنا۔
۴۔ عملی سبق: میاں بیوی کے تعلقات میں جھگڑے کی جگہ مفاہمت اختیار کرو؛ چار مہینے اللہ کی مہلت ہیں — اس سے فائدہ اٹھاؤ۔"""
),
234: (
"اور اگر وہ طلاق کا ارادہ کریں تو بے شک اللہ سننے والا جاننے والا ہے۔",
"""۱۔ ایلاء کی آخری حد — اگر رجوع نہ ہو تو طلاق کا فیصلہ۔
۲۔ ’’وَإِنْ عَزَمُوا الطَّلَاقَ‘‘ — اور اگر وہ طلاق کا ارادہ کریں — یعنی چار مہینوں کے بعد بھی صلح نہ ہو۔
۳۔ ’’فَإِنَّ اللّٰہَ سَمِيعٌ عَلِيمٌ‘‘ — تو بے شک اللہ سننے والا جاننے والا ہے — یعنی اللہ ان کے ارادے اور نیتوں کو جانتا ہے۔
۴۔ اگر چار مہینوں تک کوئی بہتری نہ ہو تو طلاق جائز ہے — لیکن ترجیح صلح کی ہے۔
۵۔ عملی سبق: جھگڑے کی انتہا میں بھی صلح کی کوشش جاری رکھو؛ طلاق آخری حل ہے۔"""
),
235: (
"اور طلاق شدہ عورتیں اپنے آپ کو تین حیض تک روکے رہیں — اور ان کے لیے حلال نہیں کہ چھپا لیں وہ جو اللہ نے ان کے رحم میں پیدا کیا ہو — اگر وہ اللہ اور قیامت کے دن پر ایمان رکھتی ہیں — اور ان کے خاوند اس (مدت) میں انہیں واپس لینے کے زیادہ حق دار ہیں اگر وہ اصلاح چاہتے ہیں — اور (عورتوں) کے لیے ویسے ہی حقوق ہیں جیسے ان پر (مردوں کے) ہیں معروف طریقہ سے — اور مردوں کے لیے ان پر ایک درجہ فوقیت ہے — اور اللہ عزت والا حکمت والا ہے۔",
"""۱۔ طلاق کے بعد عدت کا حکم — تین حیض کے دور۔
۲۔ ’’وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَاثَۃَ قُرُوءٍ‘‘ — اور طلاق شدہ عورتیں اپنے آپ کو تین حیض تک روکے رہیں — یعنی عدت تین حیض ہے۔
۳۔ ’’وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ اللّٰہُ فِي أَرْحَامِهِنَّ‘‘ — اور ان کے لیے حلال نہیں کہ چھپا لیں وہ جو اللہ نے ان کے رحم میں پیدا کیا ہو — یعنی حمل کی حقیقت چھپانا منع ہے۔
۴۔ ’’وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِنْ أَرَادُوا إِصْلَاحًا‘‘ — اور ان کے خاوند اس (مدت) میں انہیں واپس لینے کے زیادہ حق دار ہیں اگر وہ اصلاح چاہتے ہیں — یعنی عدت میں رجوع کا حق خاوند کو ہے۔
۵۔ ’’وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ‘‘ — اور (عورتوں) کے لیے ویسے ہی حقوق ہیں جیسے ان پر (مردوں کے) ہیں معروف طریقہ سے — یعنی میاں بیوی کے ایک دوسرے پر برابر حقوق ہیں۔
۶۔ ’’وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَۃٌ‘‘ — اور مردوں کے لیے ان پر ایک درجہ فوقیت ہے — یعنی خرچ اور ذمہ داری خاوند پر ہے، اسی لیے اس کا درجہ بڑھ کر ہے۔
۷۔ ’’وَاللّٰہُ عَزِيزٌ حَكِيمٌ‘‘ — اور اللہ عزت والا حکمت والا ہے۔
۸۔ عملی سبق: میاں بیوی کے حقوق اور ذمہ داریاں سمجھ کر عمل کرو؛ عدت کی حیثیت اللہ کے نزدیک اہم ہے۔"""
),
236: (
"طلاق دو مرتبہ ہے — پھر (اس کے بعد) یا تو معروف طریقہ سے روکنا ہے یا احسان کے ساتھ چھوڑ دینا ہے — اور تمہارے لیے حلال نہیں کہ واپس لے لو اس میں سے جو تم نے انہیں دیا کچھ بھی — سوائے اس صورت میں کہ دونوں ڈریں کہ اللہ کی حدود قائم نہیں رکھ سکتے — پھر اگر تم ڈرو کہ (وہ دونوں) اللہ کی حدود قائم نہیں رکھ سکتے تو (عورت) جو بدلہ دے تو اس پر کوئی گناہ نہیں — یہ اللہ کی حدود ہیں پس ان سے تجاوز نہ کرو — اور جو کوئی اللہ کی حدود سے تجاوز کرے تو وہی ظالم ہیں۔",
"""۱۔ طلاق کی تعداد اور اس کے احکام — تین مواقع (دو طلاق، ایک واپسی؛ تیسری طلاق حتمی)۔
۲۔ ’’الطَّلَاقُ مَرَّتَانِ فَإِمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ‘‘ — طلاق دو مرتبہ ہے — پھر (اس کے بعد) یا تو معروف طریقہ سے روکنا ہے یا احسان کے ساتھ چھوڑ دینا ہے — یعنی دو طلاقوں میں رجوع ممکن ہے؛ تیسری میں مکمل علیحدگی۔
۳۔ ’’وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئًا‘‘ — اور تمہارے لیے حلال نہیں کہ واپس لے لو اس میں سے جو تم نے انہیں دیا کچھ بھی — یعنی مہر کی واپسی منع ہے۔
۴۔ ’’إِلَّا أَن يَخَافَا أَلَّا يُقِيمَا حُدُودَ اللّٰہِ‘‘ — سوائے اس صورت میں کہ دونوں ڈریں کہ اللہ کی حدود قائم نہیں رکھ سکتے — یعنی صرف یہ ہی صورت کہ میاں بیوی ایک ساتھ نہیں رہ سکتے — تب ’’خلع‘‘ (فتح) کی اجازت۔
۵۔ ’’تِلْكَ حُدُودُ اللّٰہِ فَلَا تَعْتَدُوهَا‘‘ — یہ اللہ کی حدود ہیں پس ان سے تجاوز نہ کرو — یعنی اللہ کے مقررہ حدود میں رہو۔
۶۔ ’’وَمَن يَتَعَدَّ حُدُودَ اللّٰہِ فَأُولَٰئِكَ هُمُ الظَّالِمُونَ‘‘ — اور جو کوئی اللہ کی حدود سے تجاوز کرے تو وہی ظالم ہیں۔
۷۔ عملی سبق: طلاق کی مقررہ تعداد اور حدود کو پوری طرح سمجھو؛ خلع صرف باہمی مفاہمت سے۔"""
),
237: (
"پھر اگر اس نے تیسری طلاق دی تو وہ اس کے لیے حلال نہیں یہاں تک کہ وہ دوسرے شوہر سے نکاح کرے — پھر اگر وہ (دوسرا شوہر) بھی اسے طلاق دے تو (اس پر) کوئی گناہ نہیں کہ دونوں (واپس) لوٹ آئیں اگر دونوں سمجھیں کہ اللہ کی حدود قائم رکھ سکتے ہیں — اور یہ اللہ کی حدود ہیں جو اس نے علم رکھنے والوں کے لیے بیان کیں۔",
"""۱۔ تیسری طلاق کے بعد کی صورت — عارضی دوسرے شوہر سے نکاح لازمی۔
۲۔ ’’فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِن بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُ‘‘ — پھر اگر اس نے تیسری طلاق دی تو وہ اس کے لیے حلال نہیں یہاں تک کہ وہ دوسرے شوہر سے نکاح کرے — یعنی تیسری طلاق کے بعد رجوع کے لیے دوسرا نکاح اور اس کا فطرتی خاتمہ/طلاق ضروری ہے۔
۳۔ ’’فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَا أَن يَتَرَاجَعَا إِن ظَنَّا أَن يُقِيمَا حُدُودَ اللّٰہِ‘‘ — پھر اگر وہ (دوسرا شوہر) بھی اسے طلاق دے تو (اس پر) کوئی گناہ نہیں کہ دونوں (واپس) لوٹ آئیں اگر دونوں سمجھیں کہ اللہ کی حدود قائم رکھ سکتے ہیں — یعنی آزادانہ دوسرا نکاح اور اس کے بعد واپس آنا ممکن ہے۔
۴۔ ’’وَتِلْكَ حُدُودُ اللّٰہِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ‘‘ — اور یہ اللہ کی حدود ہیں جو اس نے علم رکھنے والوں کے لیے بیان کیں — یعنی یہ احکام علم رکھنے والوں پر فرض ہیں۔
۵۔ عملی سبق: طلاق کو ہلکا نہ سمجھو؛ اللہ کی حدود کو پوری طرح سمجھو اور اس کی خلاف ورزی سے بچو۔"""
),
}
